const crypto = require('crypto');

/**
 * Sanitiza el nombre del workflow para eliminar caracteres conflictivos antes de subir el archivo a github
 */
function sanitizeWorkflowName(name) {
  const replaceBy = '_'
  return (
    String(name ?? '')
      .replaceAll(/[-<>:"/\\|?*\u0000-\u001F\u007F]/g, replaceBy)
      .trim() ||
    'workflow'
  );
}

/**
 * Ordena recursivamente las claves de los objetos
 * IMPORTANTE: NO ordena arrays aquí solo ordena las keys de sus elementos que sean tipo object
 */
function sortObject(value) {
  if (Array.isArray(value)) {
    return value.map(sortObject);
  }
  if (value && typeof value === 'object') {
    return Object.keys(value)
      .sort()
      .reduce((acc, key) => {
        acc[key] = sortObject(value[key]);
        return acc;
      }, {});
  }
  return value;
}

/**
 * Normaliza y ordena determinísticamente las conexiones
 */
function normalizeConnections(connections = {}) {
  const sorted = sortObject(connections);

  for (const sourceNode of Object.keys(sorted)) {
    for (const outputType of Object.keys(sorted[sourceNode])) {
      sorted[sourceNode][outputType] = sorted[sourceNode][outputType].map(
        (connectionArray) =>
          connectionArray
            .map(sortObject)
            .sort((a, b) =>
              `${a.node}:${a.index}`.localeCompare(`${b.node}:${b.index}`)
            )
      );
    }
  }

  return sorted;
}

function canonicalizeWorkflow(workflow) {
  /**
   * Canonicalización de nodos
   * - Excluye node.id
   * - Excluye credentials.id
   * - Mantiene name y position
   * - ORDENA los nodos por name (clave estable)
   */
  const canonicalNodes = workflow.nodes
    .map((node) => {
      const { id, credentials, ...rest } = node;

      const canonicalNode = sortObject(rest);

      if (credentials) {
        canonicalNode.credentials = {};
        for (const [credType, credValue] of Object.entries(credentials)) {
          canonicalNode.credentials[credType] = {
            name: credValue.name,
          };
        }
      }

      return canonicalNode;
    })
    .sort((a, b) => a.name.localeCompare(b.name));

  /**
   * Workflow canónico final
   * SOLO toma los campos que definen el comportamiento real
   */
  const canonicalWorkflow = {
    nodes: canonicalNodes,
    connections: normalizeConnections(workflow.connections),
    settings: sortObject(workflow.settings ?? {}),
  };

  return sortObject(canonicalWorkflow);
}

/* =========================
   Generación de SHA
   ========================= */

let response = [];

for (const item of $('get_not_archived').all()) {
  const canonical = canonicalizeWorkflow(item.json);
  const canonicalString = JSON.stringify(canonical);

  const sha = crypto
    .createHash('sha256')
    .update(canonicalString)
    .digest('hex');

  response.push({
    sha,
    id: item.json.id,
    name: sanitizeWorkflowName(item.json.name),
    content: item.json,
  });
}

return response;

/*** 
* Entradas 
***/

//workflows de n8n
const n8nWorkflows = $('get_file_sha').all().map(node => node.json); 

//archivos del repo de Github
const githubFiles = $('list_files').all().map(node => node.json);  

//caracter separador
const separatorCharacter = $('config').first().json.separator_character;

/*** 
* Helpers 
***/

//Extraer los bloques de información del nombre de los archivos de github <id>:<sha>:<name>.json
function parseGithubFilename(filename) {
  const clean = filename.replace(/\.json$/, '');
  const parts = clean.split(separatorCharacter);

  return {
    id: parts[0],
    sha: parts[1],
    name: parts.slice(2).join(separatorCharacter)
  };
}

//Ignorar archivos de Github que no sigan el patrón de nombre de los flujos (README, otros json, etc.)
function isWorkflowFile(filename, escapedSeparator = separatorCharacter) {
  const regex = new RegExp(
    `^[^${escapedSeparator}]+${escapedSeparator}[a-f0-9]{8,}${escapedSeparator}.*\\.json$`,
    'i'
  );

  //return /^[^:]+:[a-f0-9]{8,}:.*\.json$/i.test(filename);
  return regex.test(filename);
}

/*** 
* Pre procesamiento 
***/

//Indexar los archivos de GitHub por id del workflow
const githubById = new Map();

for (const file of githubFiles) {
  if (!isWorkflowFile(file.name)) {
    continue;
  }
  const parsed = parseGithubFilename(file.name);

  githubById.set(parsed.id, {
    ...parsed,
    fileSha: file.sha,
    path: file.path,
    originalName: file.name
  });
}

//Indexar los archivos de n8n por id del workflow
const n8nById = new Map();
for (const wf of n8nWorkflows) {
  n8nById.set(wf.id, wf);
}

/*** 
* Lógica de comparación 
***/

//Archivos que tienen cambios pero su nombre es el mismo
const changedContentSameName = [];

//Archivos que fueron renombrados independientemente de si tuvieron cambios o no
const renamed = [];

//Nuevos workflows
const newWorkflows = [];

//Workflows que ha sido eliminados de n8n
const deletedWorkflows = [];

// Comparar n8n → GitHub
for (const wf of n8nWorkflows) {
  const gh = githubById.get(wf.id);

  // Nuevo workflow
  if (!gh) {
    newWorkflows.push(wf);
    continue;
  }

  const sameName = gh.name === wf.name;
  const sameSha = gh.sha === wf.sha;

  //Workflow Renombrado
  if (!sameName) {
    renamed.push({
      workflow: wf,
      github: gh
    });
    continue;
  }

  //Workflow con cambios pero el mismo nombre
  if (!sameSha) {
    changedContentSameName.push({
      workflow: wf,
      github: gh
    });
  }
}

//Workflow eliminado en n8n (GitHub → n8n)
for (const [id, gh] of githubById.entries()) {
  if (!n8nById.has(id)) {
    deletedWorkflows.push(gh);
  }
}

// item único con los 4 arreglos
return [
  {
    changedContentSameName,
    renamed,
    newWorkflows,
    deletedWorkflows
  }
];
